CREATE TABLE "category_nodes" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "type" TEXT NOT NULL CHECK(type IN ('category','subcategory')), "parent_id" TEXT NULL REFERENCES category_nodes (id), "archived" INTEGER NOT NULL DEFAULT 0 CHECK ("archived" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0, "icon" TEXT NULL, "color" INTEGER NULL, PRIMARY KEY ("id"), UNIQUE ("name", "parent_id"), CHECK ((type = 'category' AND parent_id IS NULL) OR (type = 'subcategory' AND parent_id IS NOT NULL)));
CREATE TABLE "budget_months" ("id" TEXT NOT NULL, "currency" TEXT NOT NULL DEFAULT 'PKR', "total_budget_minor" INTEGER NOT NULL DEFAULT 0 CHECK(total_budget_minor >= 0), "saving_target_minor" INTEGER NOT NULL DEFAULT 0 CHECK(saving_target_minor >= 0), "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "budget_limits" ("id" TEXT NOT NULL, "budget_month_id" TEXT NOT NULL REFERENCES budget_months (id) ON DELETE CASCADE, "node_id" TEXT NOT NULL REFERENCES category_nodes (id) ON DELETE CASCADE, "limit_minor" INTEGER NOT NULL CHECK(limit_minor >= 0), PRIMARY KEY ("id"), UNIQUE ("budget_month_id", "node_id"));
CREATE TABLE "transactions" ("id" TEXT NOT NULL, "type" TEXT NOT NULL CHECK(type IN ('income','expense')), "amount_minor" INTEGER NOT NULL CHECK(amount_minor > 0), "date_millis" INTEGER NOT NULL, "month_id" TEXT NOT NULL, "subcategory_id" TEXT NULL REFERENCES category_nodes (id), "note" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"), CHECK ((type = 'expense' AND subcategory_id IS NOT NULL) OR (type = 'income' AND subcategory_id IS NULL)));
CREATE TABLE "recurring_templates" ("id" TEXT NOT NULL, "title" TEXT NOT NULL CHECK(length(trim(title)) > 0), "amount_minor" INTEGER NOT NULL CHECK(amount_minor > 0), "type" TEXT NOT NULL CHECK(type IN ('income','expense')), "subcategory_id" TEXT NULL REFERENCES category_nodes (id), "note" TEXT NULL, "day_of_month" INTEGER NOT NULL DEFAULT 1 CHECK(day_of_month BETWEEN 1 AND 31), "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), "created_at_millis" INTEGER NOT NULL, PRIMARY KEY ("id"), CHECK ((type = 'expense' AND subcategory_id IS NOT NULL) OR (type = 'income' AND subcategory_id IS NULL)));
CREATE TABLE "recurring_applied" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "template_id" TEXT NOT NULL REFERENCES recurring_templates (id) ON DELETE CASCADE, "month_id" TEXT NOT NULL, "applied_at_millis" INTEGER NOT NULL, UNIQUE(template_id, month_id));
CREATE UNIQUE INDEX category_names ON category_nodes (name) WHERE type = 'category';
PRAGMA user_version=3;
